from django.db import migrations, models


FIBONACCI_POINTS = ["1", "2", "3", "5", "8", "13", "21"]
STORY_POINT_ESTIMATE_NAME = "Story point"


def add_story_point_estimates(apps, schema_editor):
    """Give every existing project without an active estimate the Fibonacci story point system.

    New projects get it from the project signal; this covers projects created before it existed.
    """
    Project = apps.get_model("db", "Project")
    Estimate = apps.get_model("db", "Estimate")
    EstimatePoint = apps.get_model("db", "EstimatePoint")

    projects = Project.objects.filter(estimate__isnull=True, deleted_at__isnull=True)
    for project in projects.iterator():
        estimate, _ = Estimate.objects.get_or_create(
            project_id=project.id,
            name=STORY_POINT_ESTIMATE_NAME,
            deleted_at__isnull=True,
            defaults={"workspace_id": project.workspace_id, "type": "points", "last_used": True},
        )
        if not EstimatePoint.objects.filter(estimate_id=estimate.id, deleted_at__isnull=True).exists():
            EstimatePoint.objects.bulk_create(
                [
                    EstimatePoint(
                        estimate_id=estimate.id,
                        key=index,
                        value=value,
                        project_id=project.id,
                        workspace_id=project.workspace_id,
                    )
                    for index, value in enumerate(FIBONACCI_POINTS, start=1)
                ]
            )
        Project.objects.filter(pk=project.pk, estimate__isnull=True).update(estimate_id=estimate.id)


